SELECT * FROM crypto_ai.execution_opportunity WHERE (symbol='EGLDUSDT' AND started_at <= '2026-10-11 22:40:04' AND updated_at >= '2026-10-11 20:50:00') OR (symbol='XRPUSDT' AND updated_at BETWEEN '2026-10-12 02:20:00' AND '2026-10-12 02:36:00') OR (symbol='DOGEUSDT' AND updated_at BETWEEN '2026-10-12 03:40:00' AND '2026-10-12 04:03:00') OR (symbol='SHIBUSDT' AND updated_at BETWEEN '2026-10-12 06:30:00' AND '2026-10-12 06:37:00') OR (symbol='ACEUSDT' AND updated_at BETWEEN '2026-10-12 09:50:00' AND '2026-10-12 09:58:00') ORDER BY symbol, started_at LIMIT 40;